import random

# three boxes: new or missed facts, getting there, known
boxes = {1: [(6, 7), (7, 8), (8, 6), (12, 7)], 2: [(4, 6), (3, 8)], 3: [(6, 6)]}
review_every = {1: 1, 2: 2, 3: 5}          # box 1 daily, box 2 every 2 days, box 3 every 5

def todays_cards(day):
    return [f for box, facts in boxes.items() if day % review_every[box] == 0 for f in facts]

def answer(fact, correct):
    for box, facts in boxes.items():
        if fact in facts:
            facts.remove(fact)
            new_box = min(box + 1, 3) if correct else 1   # a miss always goes back to box 1
            boxes[new_box].append(fact)
            return new_box

random.seed(4)
for day in (1, 2):
    cards = todays_cards(day)
    print(f"Day {day}: {len(cards)} cards")
    for a, b in cards:
        correct = random.random() < 0.7         # stand-in for the child's answer
        moved_to = answer((a, b), correct)
        print(f"  {a} x {b} = {a*b:<3} {'right' if correct else 'missed'} -> box {moved_to}")
